create table if not exists spiritual.astro_events ( id bigint generated always as identity primary key, event_date timestamptz not null, sunrise timestamptz, sunset timestamptz, solar_noon timestamptz, day_length_seconds integer, is_equinox boolean default false, is_solstice boolean default false, season text check (season in ('spring', 'summer', 'autumn', 'winter')), moon_rise timestamptz, moon_set timestamptz, moon_phase spiritual.moon_phase, moon_illumination numeric(5,2), moon_age_days numeric(6,2), moon_distance_km numeric(10,2), moon_sign text, lunar_month_day smallint, next_new_moon timestamptz, next_full_moon timestamptz, source text default 'api', calculated_by uuid references identity.profiles (id), tenant_id uuid references core.tenants (id), created_at timestamptz default now(), unique (event_date) );
